/** `[family, category, unitsPerEm, ascent, descent, lineGap, xWidthAvg]` per family. */
export const FONT_METRICS: readonly (readonly [
  string,
  string,
  number,
  number,
  number,
  number,
  number,
])[] = ROWS.split("\n").map((line) => {
  const [family, category, ...nums] = line.split("|");
  const [unitsPerEm, ascent, descent, lineGap, xWidthAvg] = nums.map(Number);
  return [family, CATEGORIES[Number(category)], unitsPerEm, ascent, descent, lineGap, xWidthAvg];
});
